import{_ as a,o as i,c as o,a2 as r}from"./chunks/framework.CgxQ0r6v.js";const m=JSON.parse('{"title":"🛰️ Guía de Laboratorio: Implementación con MikroTik (RouterOS)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Redes/documentacion/II-V/Guia_Practica_MikroTik.md","filePath":"materias/Redes/documentacion/II-V/Guia_Practica_MikroTik.md"}'),t={name:"materias/Redes/documentacion/II-V/Guia_Practica_MikroTik.md"};function n(c,e,l,s,d,u){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="🛰️-guia-de-laboratorio-implementacion-con-mikrotik-routeros" tabindex="-1">🛰️ Guía de Laboratorio: Implementación con MikroTik (RouterOS) <a class="header-anchor" href="#🛰️-guia-de-laboratorio-implementacion-con-mikrotik-routeros" aria-label="Permalink to &quot;🛰️ Guía de Laboratorio: Implementación con MikroTik (RouterOS)&quot;">​</a></h1><p>Esta guía complementaria está diseñada para integrar el equipo físico MikroTik disponible en el laboratorio con los objetivos académicos del Trayecto II, Trimestre V.</p><hr><h2 id="_1-conceptos-fundamentales" tabindex="-1">1. Conceptos Fundamentales <a class="header-anchor" href="#_1-conceptos-fundamentales" aria-label="Permalink to &quot;1. Conceptos Fundamentales&quot;">​</a></h2><p>MikroTik no es solo un router; es una computadora especializada que corre un sistema operativo basado en Linux llamado <strong>RouterOS</strong>.</p><p><strong>Para el programador:</strong> Piensa en MikroTik como un servidor con una estructura de configuración jerárquica, donde cada comando en la terminal tiene su equivalente en la interfaz gráfica.</p><hr><h2 id="_2-acceso-inicial-al-equipo" tabindex="-1">2. Acceso Inicial al Equipo <a class="header-anchor" href="#_2-acceso-inicial-al-equipo" aria-label="Permalink to &quot;2. Acceso Inicial al Equipo&quot;">​</a></h2><p>Para configurar el equipo desde cero, utilizaremos la herramienta oficial <strong>Winbox</strong> (disponible en mikrotik.com).</p><ol><li><strong>Conexión Física:</strong> Conecta tu PC a cualquier puerto del MikroTik (excepto el puerto 1, que suele ser para internet).</li><li><strong>Acceso por MAC Address:</strong> Winbox permite conectarse incluso si el equipo no tiene una IP configurada. Ve a la pestaña &quot;Neighbors&quot; y haz clic en la dirección MAC del equipo.</li><li><strong>Credenciales por defecto:</strong><ul><li><strong>User:</strong> <code>admin</code></li><li><strong>Password:</strong> (vacío)</li></ul></li></ol><hr><h2 id="_3-configuracion-base-practica-para-evaluacion-2-direccionamiento" tabindex="-1">3. Configuración Base (Práctica para Evaluación 2: Direccionamiento) <a class="header-anchor" href="#_3-configuracion-base-practica-para-evaluacion-2-direccionamiento" aria-label="Permalink to &quot;3. Configuración Base (Práctica para Evaluación 2: Direccionamiento)&quot;">​</a></h2><p>El objetivo es crear una red local funcional para el laboratorio.</p><h3 id="a-identificacion-de-interfaces" tabindex="-1">A. Identificación de Interfaces <a class="header-anchor" href="#a-identificacion-de-interfaces" aria-label="Permalink to &quot;A. Identificación de Interfaces&quot;">​</a></h3><p>Es buena práctica renombrar los puertos para evitar errores:</p><ul><li><code>ether1</code> -&gt; <code>ether1-WAN</code> (Internet)</li><li><code>ether2</code> -&gt; <code>ether2-LAN-Docente</code></li><li><code>ether3</code> -&gt; <code>ether3-LAN-Alumnos</code></li></ul><h3 id="b-asignacion-de-direcciones-ip" tabindex="-1">B. Asignación de Direcciones IP <a class="header-anchor" href="#b-asignacion-de-direcciones-ip" aria-label="Permalink to &quot;B. Asignación de Direcciones IP&quot;">​</a></h3><p><em>Ruta: IP &gt; Addresses</em></p><ul><li>Asigna <code>192.168.10.1/24</code> a la interfaz <code>ether3-LAN-Alumnos</code>.</li><li><strong>Explicación Pedagógica:</strong> Aquí los alumnos ven cómo el router se convierte en el <strong>Default Gateway</strong> de esa red.</li></ul><h3 id="c-configuracion-del-servidor-dhcp" tabindex="-1">C. Configuración del Servidor DHCP <a class="header-anchor" href="#c-configuracion-del-servidor-dhcp" aria-label="Permalink to &quot;C. Configuración del Servidor DHCP&quot;">​</a></h3><p><em>Ruta: IP &gt; DHCP Server &gt; DHCP Setup</em></p><ol><li>Selecciona la interfaz <code>ether3-LAN-Alumnos</code>.</li><li>Define el rango de direcciones (Pool): <code>192.168.10.10 - 192.168.10.250</code>.</li><li>Establece el Gateway: <code>192.168.10.1</code>.</li></ol><ul><li><strong>Resultado:</strong> Cualquier PC conectada al puerto 3 recibirá una IP automáticamente.</li></ul><hr><h2 id="_4-salida-a-internet-practica-para-evaluacion-3-servicios" tabindex="-1">4. Salida a Internet (Práctica para Evaluación 3: Servicios) <a class="header-anchor" href="#_4-salida-a-internet-practica-para-evaluacion-3-servicios" aria-label="Permalink to &quot;4. Salida a Internet (Práctica para Evaluación 3: Servicios)&quot;">​</a></h2><p>Para que las PCs del laboratorio naveguen, necesitamos configurar el <strong>NAT (Network Address Translation)</strong>.</p><h3 id="a-cliente-dhcp-wan" tabindex="-1">A. Cliente DHCP (WAN) <a class="header-anchor" href="#a-cliente-dhcp-wan" aria-label="Permalink to &quot;A. Cliente DHCP (WAN)&quot;">​</a></h3><p><em>Ruta: IP &gt; DHCP Client</em></p><ul><li>Agrega un cliente en <code>ether1-WAN</code>. Esto permitirá que el MikroTik reciba internet del proveedor de la universidad.</li></ul><h3 id="b-nat-masquerade-el-puente" tabindex="-1">B. NAT Masquerade (El &quot;Puente&quot;) <a class="header-anchor" href="#b-nat-masquerade-el-puente" aria-label="Permalink to &quot;B. NAT Masquerade (El &quot;Puente&quot;)&quot;">​</a></h3><p><em>Ruta: IP &gt; Firewall &gt; NAT</em></p><ul><li><strong>Chain:</strong> <code>srcnat</code></li><li><strong>Out. Interface:</strong> <code>ether1-WAN</code></li><li><strong>Action:</strong> <code>masquerade</code></li><li><strong>Concepto:</strong> Traduce las IPs privadas de los alumnos a la IP pública del router para poder salir a internet.</li></ul><hr><h2 id="_5-seguridad-perimetral-practica-para-evaluacion-4" tabindex="-1">5. Seguridad Perimetral (Práctica para Evaluación 4) <a class="header-anchor" href="#_5-seguridad-perimetral-practica-para-evaluacion-4" aria-label="Permalink to &quot;5. Seguridad Perimetral (Práctica para Evaluación 4)&quot;">​</a></h2><p>MikroTik utiliza un firewall basado en estados (stateful).</p><h3 id="bloqueo-por-ip-lista-negra" tabindex="-1">Bloqueo por IP (Lista Negra) <a class="header-anchor" href="#bloqueo-por-ip-lista-negra" aria-label="Permalink to &quot;Bloqueo por IP (Lista Negra)&quot;">​</a></h3><p><em>Ruta: IP &gt; Firewall &gt; Filter Rules</em></p><ol><li><strong>Chain:</strong> <code>forward</code></li><li><strong>Src. Address:</strong> <code>192.168.10.50</code> (IP de un alumno &quot;travieso&quot;)</li><li><strong>Action:</strong> <code>drop</code></li></ol><ul><li><strong>Reto para la clase:</strong> ¿Cómo harías para que ese alumno solo tenga bloqueado el internet pero pueda ver el servidor local?</li></ul><hr><h2 id="📘-diccionario-mikrotik-para-la-clase" tabindex="-1">📘 Diccionario MikroTik para la Clase <a class="header-anchor" href="#📘-diccionario-mikrotik-para-la-clase" aria-label="Permalink to &quot;📘 Diccionario MikroTik para la Clase&quot;">​</a></h2><ul><li><strong>Winbox:</strong> Interfaz gráfica nativa de gestión.</li><li><strong>Bridge:</strong> Agrupación lógica de puertos físicos para que funcionen como un Switch.</li><li><strong>Safe Mode:</strong> Botón vital en Winbox. Si haces un cambio que te desconecta, el router deshace el cambio automáticamente al perder la conexión. (¡Ideal para estudiantes!).</li><li><strong>Torch:</strong> Herramienta de monitoreo en tiempo real para ver qué tráfico está pasando por una interfaz específica.</li></ul>',42)])])}const g=a(t,[["render",n]]);export{m as __pageData,g as default};
